(()=>{document.getElementById("year").textContent=(new Date).getFullYear();const e=window.matchMedia("(prefers-reduced-motion: reduce)"),t=document.querySelectorAll(".postmortem__timeline");if(t.length&&"IntersectionObserver"in window&&!e.matches){document.documentElement.classList.add("motion");const e=new IntersectionObserver(t=>{t.forEach(t=>{t.isIntersecting&&(t.target.classList.add("is-drawn"),e.unobserve(t.target))})},{threshold:.35});t.forEach(t=>e.observe(t))}const n=document.querySelector(".form");if(n&&window.fetch){const e=n.querySelector(".form__status"),t=n.querySelector('button[type="submit"]'),r=(t,n)=>{e.textContent=t,e.className="form__status"+(n?" is-"+n:"")};n.addEventListener("submit",async e=>{e.preventDefault(),n.classList.add("is-sending"),t.disabled=!0,r("Sending…");try{const e=await fetch(n.action,{method:"POST",body:new FormData(n),headers:{Accept:"application/json"}});if(!e.ok)throw new Error(e.status);n.reset(),r("Sent. Thank you, I will reply by email.","sent")}catch(e){r("Could not send. Check your connection and try again, or message me on LinkedIn.","error")}finally{n.classList.remove("is-sending"),t.disabled=!1}})}const r=[...document.querySelectorAll(".index a")];if(!r.length||!("IntersectionObserver"in window))return;const o=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(e=>{let t=r.findIndex(t=>t.getAttribute("href")==="#"+e);for(;t>0&&null===r[t].offsetParent;)t--;t<0||r.forEach((e,n)=>{const r=n===t;e.classList.toggle("is-active",r),r?e.setAttribute("aria-current","true"):e.removeAttribute("aria-current")})})(e.target.id)})},{rootMargin:"-30% 0px -65% 0px"});r.map(e=>document.querySelector(e.getAttribute("href"))).filter(Boolean).forEach(e=>o.observe(e))})();